            longitude: startLongitude,
            latitude: startLatitude,
            type: 'route'
          });
          addedKeys.add(startKey);
        }
      }
      day.items.filter(item => item.longitude && item.latitude).forEach(item => {
        let name = '未知点位';
        if (item.type === 'attraction') name = item.attractionName || '未知景点';else if (item.type === 'food') name = item.foodName || item.shopName || '未知美食';else if (item.type === 'hotel') name = item.hotelName || '未知酒店';else if (item.type === 'route') name = item.toLocation || item.fromLocation || '未知地点';
        if (item.type === 'route' && item.longitude === startLongitude && item.latitude === startLatitude) return;
        const itemKey = `${item.longitude},${item.latitude}`;
        if (!addedKeys.has(itemKey)) {
          attractions.push({
