          } else {
            this.$message.error('删除失败');
          }
        } catch (error) {
          this.$message.error('删除失败');
        }
      }).catch(() => {
        this.$message.info('已取消删除');
      });
    },
    getImages(imagesStr) {
      if (!imagesStr) return [];
      try {
        return JSON.parse(imagesStr);
      } catch (e) {
        return imagesStr.split(',').filter(img => img);
      }
    },
    getTransportText(type) {
      const map = {
        'drive': '自驾',
        'bus': '公交',
        'taxi': '打车',
        'walking': '步行',
        'walk': '步行'
      };
      return map[type] || type;
    },
    getTypeText(type) {
      const map = {
        'attraction': '景点',
        'food': '美食',
        'hotel': '酒店',
        'route': '交通'
      };
      return map[type] || '未知';
    },
    formatDuration(minutes) {
      if (!minutes && minutes !== 0) return '暂无数据';
      const hours = Math.floor(minutes / 60);
      const mins = minutes % 60;
      if (hours > 0 && mins > 0) return `${hours}小时${mins}分钟`;else if (hours > 0) return `${hours}小时`;else return `${mins}分钟`;
    },
